INSERT INTO TempVendaImovel ( LinkVenda, CodAtribuiEmpresa, EmpVinculada, CodigoParceiro, DataMovto, CodImovel, CodHistorico, Plano3, ContaFinanceira, NumDoc, Complemento, ValorDebito, AgrupadorVenda, DataVencto, Integracao, SofreReajuste, ClassificacaoVenda, Efetuado, CodAnteriorEmpresa, IndiceReajuste, ValorOriginalImovel, CodigoCondPagto )
SELECT Formulários!VendaImovelVendido!VendaCondPagto.Formulário!LinkVenda AS Link, Formulários!VendaImovelVendido!EmpVinculada AS AtribuiEmpresa, "1" AS Empresa, Formulários!VendaImovelVendido!Proprietario AS Parceiro, Formulários!VendaImovelVendido!VendaCondPagto.Formulário!VenctoParcela AS DtMov, Formulários!VendaImovelVendido!CodImovel AS Imovel, "8 " AS Historico, "2" AS Plano3, "2" AS Financeira, Formulários!VendaImovelVendido!VendaCondPagto.Formulário!Documento AS Doc, Formulários!VendaImovelVendido!VendaCondPagto.Formulário!Complemento & " - " & Formulários!VendaImovelVendido!NomeVinculada AS Complem, Formulários!VendaImovelVendido!VendaCondPagto.Formulário!ValorInicial AS ValorDeb, Formulários!VendaImovelVendido!CodImovel AS Agrupar, Formulários!VendaImovelVendido!VendaCondPagto.Formulário!VenctoParcela AS Vencto, Formulários!VendaImovelVendido!VendaCondPagto.Formulário!Integracao AS Integra, Formulários!VendaImovelVendido!AplicarReajuste AS Reajusta, "A" AS Cassifica, True AS Efetuado, "1" AS CodAnteriorEmpresa, Formulários!VendaImovelVendido!IndiceReajuste AS IndiceReajuste, Formulários!VendaImovelVendido!VendaCondPagto.Formulário!ValorInicial AS ValorInicial, Formulários!VendaImovelVendido!VendaCondPagto.Formulário!CodPagtoImovel AS CodPagto;
